mapper.select:
SELECT G.EVENT_ID, G.EVENT_TYPE, G.TEMPLATE_ID, T.TEMPLATE_NAME, G.HIST_EVENT_ID, H.TITLE AS HIST_TITLE, H.COUNTRY_CODE, H.START_YEAR, H.END_YEAR, G.TITLE, G.BASE_TEXT, G.IS_CHOICE, G.AI_NARRATE, G.IS_REVIEWED, G.PROBABILITY, (SELECT COUNT(*) FROM EVENT_CHOICE C WHERE C.EVENT_ID = G.EVENT_ID) AS CHOICE_COUNT FROM GAME_EVENT G LEFT JOIN EVENT_TEMPLATE T ON G.TEMPLATE_ID = T.TEMPLATE_ID LEFT JOIN HISTORY_EVENT H ON G.HIST_EVENT_ID = H.EVENT_ID
AND G.EVENT_ID = #{eventId}
AND G.EVENT_TYPE = #{type}
AND G.IS_REVIEWED = #{reviewed}
AND G.AI_NARRATE = #{aiNarrate}
AND (G.EVENT_ID LIKE '%' || #{keyword} || '%' OR G.TITLE LIKE '%' || #{keyword} || '%' OR G.BASE_TEXT LIKE '%' || #{keyword} || '%' OR H.TITLE LIKE '%' || #{keyword} || '%')
ORDER BY G.EVENT_TYPE DESC, H.COUNTRY_CODE NULLS FIRST, H.START_YEAR NULLS FIRST, G.EVENT_ID

mapper.update:
UPDATE EVENT_TEMPLATE SET
BASE_PROB = #{baseProb, jdbcType=NUMERIC},
MIN_AGE = #{minAge, jdbcType=NUMERIC},
MAX_AGE = #{maxAge, jdbcType=NUMERIC}
WHERE TEMPLATE_ID = #{templateId}
